INSERT /* setUserWithdrawal */
  INTO TH_USWTHD (
       USER_NUMB
     , USER_IDHS
     , WTHD_TYPE
     , WTHD_RSON
     , RSON_CNTN
     , WTHD_STAT
     , REQU_DATE
     , DELT_DATE
     , PROC_DATE
     , ERRO_CNTN
) VALUES (
       #{userNumb}
     , #{userIdhs}
     , #{wthdType}
     , #{wthdRson}
     , #{rsonCntn,jdbcType=VARCHAR}
     , #{wthdStat}
     , CURRENT_TIMESTAMP
     , #{deltDate,jdbcType=TIMESTAMP}
     , #{procDate,jdbcType=TIMESTAMP}
     , #{erroCntn,jdbcType=VARCHAR}
)

